216:func BuildWorldDeltaPacket(previous WorldFullPacket, current WorldFullPacket) WorldDeltaPacket {
217:	metadata := current.Metadata
218:	metadata.BaselineID = previous.Metadata.BaselineID
219:	metadata.SnapshotID = DeltaSnapshotID(current.Metadata.Lane, current.Metadata.Sequence)
220:	metadata.SnapshotKind = SnapshotKind("delta")
221:	return WorldDeltaPacket{
222:		Type:     PacketTypeWorldDelta,
223:		Metadata: metadata,
224:		Ships: CompareLaneRecordFields(previous.Ships, current.Ships,
225:			func(record WorldShipRecord) string { return record.ID },
226:			"id",
227:		),
228:		Bullets: CompareLaneRecordFields(previous.Bullets, current.Bullets,
229:			func(record WorldBulletRecord) string { return record.ID },
230:			"id",
231:		),
232:		Asteroids: CompareLaneRecordFields(previous.Asteroids, current.Asteroids,
233:			func(record WorldAsteroidRecord) string { return record.ID },
234:			"id",
235:		),
236:		Pickups: CompareLaneRecordFields(previous.Pickups, current.Pickups,
237:			func(record WorldPickupRecord) string { return record.ID },
238:			"id",
239:		),
240:	}
241:}
